import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

import {
  Screen,
  PrimaryButton,
} from "../components/common/UI";

import "../styles/PaymentPending.css";

export default function PaymentPending() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [order, setOrder] = useState(null);
  const [polling, setPolling] = useState(true);
  const [paymentStatus, setPaymentStatus] = useState("pending");

  useEffect(() => {
    const paymentResult = searchParams.get("payment");

    if (paymentResult === "success") {
      setPaymentStatus("processing");
      // Poll for payment confirmation
      const pollInterval = setInterval(async () => {
        // TODO: Implement polling for GET /orders/:orderId
        // Check if payment.status === "succeeded"
        // If yes, navigate to success screen
        // After 30 seconds, show timeout message
      }, 2000);

      return () => clearInterval(pollInterval);
    } else if (paymentResult === "cancelled") {
      setPaymentStatus("cancelled");
    }

    // TODO: Load order details
    setOrder({
      public_id: "GR-98312",
      total: { kes: "564.00", aud: "6.24" }
    });
  }, [searchParams]);

  if (paymentStatus === "cancelled") {
    return (
      <Screen title="Payment Status">
        <div className="payment-result">
          <div className="result-symbol pending">
            ✕
          </div>
          <h2>Payment Cancelled</h2>
          <p>
            You cancelled the payment. You can try again or return to your orders.
          </p>
          <PrimaryButton onClick={() => navigate("/orders")}>
            View Orders
          </PrimaryButton>
          <button className="text-action" onClick={() => navigate("/basket")}>
            Back to Basket
          </button>
        </div>
      </Screen>
    );
  }

  return (
    <Screen title="Payment Status">
      <div className="payment-result">
        <div className="result-symbol pending">
          ◉
        </div>

        <h2>Processing Payment</h2>

        <p>
          {paymentStatus === "processing" 
            ? "Payment is being processed. We'll notify you on WhatsApp once it's confirmed."
            : "We are processing your payment. Please complete the payment on the Stripe checkout page."}
        </p>

        {order && (
          <div className="panel">
            <div className="summary-line">
              <span>Order</span>
              <b>{order.public_id}</b>
            </div>
            <div className="summary-line">
              <span>Total</span>
              <b className="orange">
                KSh {order.total.kes}
                <span className="aud-price">≈ AUD {order.total.aud}</span>
              </b>
            </div>
          </div>
        )}

        {paymentStatus === "pending" && (
          <PrimaryButton onClick={() => navigate("/orders")}>
            View Orders
          </PrimaryButton>
        )}
      </div>
    </Screen>
  );
}
